package rules

import "testing"

// Cases ported from PHP-CS-Fixer's StringableForToStringFixerTest.
func TestStringableForToStringPhpCsFixerCases(t *testing.T) {
	t.Parallel()
	aliasRunUpstreamCases(t, StringableForToString{}, []aliasUpstreamCase{
		{"no method", nil, "<?php class Foo {}", "<?php class Foo {}"},
		{"wrong method name", nil,
			`<?php class Foo { public function toString() { return "Foo"; } }`,
			`<?php class Foo { public function toString() { return "Foo"; } }`},
		{"already implements, upper", nil,
			`<?php class Foo implements STRINGABLE  { public function __toString() { return "Foo"; } }`,
			`<?php class Foo implements STRINGABLE  { public function __toString() { return "Foo"; } }`},
		{"already implements, leading slash", nil,
			`<?php class Foo implements \Stringable { public function __toString() { return "Foo"; } }`,
			`<?php class Foo implements \Stringable { public function __toString() { return "Foo"; } }`},
		{"namespace, use, implements", nil,
			"<?php\n            namespace Foo;\n            use Stringable;\n            class Bar implements Stringable {\n                public function __toString() { return \"\"; }\n            }\n        ",
			"<?php\n            namespace Foo;\n            use Stringable;\n            class Bar implements Stringable {\n                public function __toString() { return \"\"; }\n            }\n        "},
		{"use alias", nil,
			"<?php\n            use Stringable as Stringy;\n            class Bar implements Stringy {\n                public function __toString() { return \"\"; }\n            }\n        ",
			"<?php\n            use Stringable as Stringy;\n            class Bar implements Stringy {\n                public function __toString() { return \"\"; }\n            }\n        "},
		{"add interface, new clause", nil,
			"<?php class Foo\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            ",
			"<?php class Foo implements \\Stringable\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            "},
		{"add interface in namespace", nil,
			"<?php namespace FooNamespace;\n            class Foo\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            ",
			"<?php namespace FooNamespace;\n            class Foo implements \\Stringable\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            "},
		{"use non-global stringable still adds", nil,
			"<?php namespace FooNamespace;\n            use Bar\\Stringable;\n            class Foo implements Stringable\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            ",
			"<?php namespace FooNamespace;\n            use Bar\\Stringable;\n            class Foo implements \\Stringable, Stringable\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            "},
		{"alias to non-stringable adds", nil,
			"<?php\nuse NotStringable as Stringy;\nclass Bar implements Stringy {\n    public function __toString() { return \"\"; }\n}",
			"<?php\nuse NotStringable as Stringy;\nclass Bar implements \\Stringable, Stringy {\n    public function __toString() { return \"\"; }\n}"},
		{"prepend to existing clause", nil,
			"<?php class Foo implements FooInterface\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            ",
			"<?php class Foo implements \\Stringable, FooInterface\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            "},
		{"after extends", nil,
			"<?php class Foo extends Bar\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            ",
			"<?php class Foo extends Bar implements \\Stringable\n            {\n                public function __toString() { return \"Foo\"; }\n            }\n            "},
		{"method name casing", nil,
			"<?php class Foo\n            {\n                public function __TOSTRING() { return \"Foo\"; }\n            }\n            ",
			"<?php class Foo implements \\Stringable\n            {\n                public function __TOSTRING() { return \"Foo\"; }\n            }\n            "},
		{"multiple classes", nil,
			"<?php\n            class Foo1 { public function __toString() { return \"1\"; } }\n            class Foo2 { public function __noString() { return \"2\"; } }\n            class Foo3 { public function __toString() { return \"3\"; } }\n",
			"<?php\n            class Foo1 implements \\Stringable { public function __toString() { return \"1\"; } }\n            class Foo2 { public function __noString() { return \"2\"; } }\n            class Foo3 implements \\Stringable { public function __toString() { return \"3\"; } }\n"},
		{"anonymous class", nil,
			"<?php new class {\n                public function __construct() {}\n                public function __toString() {}\n            };\n            ",
			"<?php new class implements \\Stringable {\n                public function __construct() {}\n                public function __toString() {}\n            };\n            "},
		{"anonymous class with parens", nil,
			"<?php new class() {\n                public function __construct() {}\n                public function __toString() {}\n            };\n            ",
			"<?php new class() implements \\Stringable {\n                public function __construct() {}\n                public function __toString() {}\n            };\n            "},
		{"namespaced blocks reset aliases", nil,
			"<?php\n                namespace Foo { use Stringable as Stringy; class C {} }\n                namespace Bar { class C implements Stringy { public function __toString() { return \"\"; } }}\n            ;\n            ",
			"<?php\n                namespace Foo { use Stringable as Stringy; class C {} }\n                namespace Bar { class C implements \\Stringable, Stringy { public function __toString() { return \"\"; } }}\n            ;\n            "},
	})
}
